#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

struct Cell {
  std::ptrdiff_t row = 0;
  std::ptrdiff_t col = 0;
};

// Groups of '#' cells joined up, down, left or right.
[[nodiscard]] std::int64_t count_islands(std::span<const std::string> grid) {
  const std::ptrdiff_t rows = std::ssize(grid);
  const std::ptrdiff_t cols = rows == 0 ? 0 : std::ssize(grid.front());
  std::vector<char> seen(static_cast<std::size_t>(rows * cols), 0);
  const auto index = [cols](std::ptrdiff_t r, std::ptrdiff_t c) { return static_cast<std::size_t>(r * cols + c); };
  std::int64_t islands = 0;
  std::vector<Cell> pending;
  for (std::ptrdiff_t r = 0; r < rows; ++r) {
    for (std::ptrdiff_t c = 0; c < cols; ++c) {
      if (grid[static_cast<std::size_t>(r)][static_cast<std::size_t>(c)] != '#' || seen[index(r, c)] != 0) continue;
      ++islands;
      seen[index(r, c)] = 1;  // marked when it is queued, not when it is taken
      pending.push_back({.row = r, .col = c});
      while (!pending.empty()) {
        const Cell here = pending.back();
        pending.pop_back();
        const std::vector<Cell> around{{here.row - 1, here.col},
                                       {here.row + 1, here.col},
                                       {here.row, here.col - 1},
                                       {here.row, here.col + 1}};
        for (const Cell& next : around) {
          if (next.row < 0 || next.row >= rows || next.col < 0 || next.col >= cols) continue;
          if (grid[static_cast<std::size_t>(next.row)][static_cast<std::size_t>(next.col)] != '#') continue;
          if (seen[index(next.row, next.col)] != 0) continue;
          seen[index(next.row, next.col)] = 1;
          pending.push_back(next);
        }
      }
    }
  }
  return islands;
}

void report(std::string_view name, std::span<const std::string> grid) {
  std::cout << std::format("{:<22}{}\n", name, count_islands(grid));
}

int main() {
  const std::vector<std::string> map{"##..#", "#..#.", ".#..#", "###.."};
  for (const std::string& row : map) std::cout << row << '\n';
  report("islands", map);
  report("all water", std::vector<std::string>{"...", "..."});
  report("all land", std::vector<std::string>{"###", "###"});
  report("one cell", std::vector<std::string>{"#"});
  report("empty grid", {});
}

