#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <random>
#include <span>
#include <string_view>
#include <utility>
#include <vector>

struct Edge {
  std::ptrdiff_t from = 0;
  std::ptrdiff_t to = 0;
};

// Bytes the container actually reserved, counted from its own capacity.
[[nodiscard]] std::int64_t bytes_of(const std::vector<std::vector<std::ptrdiff_t>>& lists) {
  std::int64_t total = static_cast<std::int64_t>(lists.capacity() * sizeof(std::vector<std::ptrdiff_t>));
  for (const std::vector<std::ptrdiff_t>& row : lists)
    total += static_cast<std::int64_t>(row.capacity() * sizeof(std::ptrdiff_t));
  return total;
}

[[nodiscard]] std::vector<std::vector<std::ptrdiff_t>> as_lists(std::ptrdiff_t n, std::span<const Edge> edges) {
  std::vector<std::vector<std::ptrdiff_t>> lists(static_cast<std::size_t>(n));
  for (const Edge& e : edges) {
    lists[static_cast<std::size_t>(e.from)].push_back(e.to);
    lists[static_cast<std::size_t>(e.to)].push_back(e.from);
  }
  return lists;
}

// One block: targets holds every neighbour, offsets says where each vertex's run starts.
struct Csr {
  std::vector<std::ptrdiff_t> offsets;
  std::vector<std::ptrdiff_t> targets;
};

[[nodiscard]] Csr as_csr(std::ptrdiff_t n, std::span<const Edge> edges) {
  Csr csr;
  csr.offsets.assign(static_cast<std::size_t>(n + 1), 0);
  for (const Edge& e : edges) {
    ++csr.offsets[static_cast<std::size_t>(e.from + 1)];
    ++csr.offsets[static_cast<std::size_t>(e.to + 1)];
  }
  for (std::ptrdiff_t i = 0; i < n; ++i)
    csr.offsets[static_cast<std::size_t>(i + 1)] += csr.offsets[static_cast<std::size_t>(i)];
  csr.targets.assign(static_cast<std::size_t>(2 * std::ssize(edges)), 0);
  std::vector<std::ptrdiff_t> next = csr.offsets;
  for (const Edge& e : edges) {
    csr.targets[static_cast<std::size_t>(next[static_cast<std::size_t>(e.from)]++)] = e.to;
    csr.targets[static_cast<std::size_t>(next[static_cast<std::size_t>(e.to)]++)] = e.from;
  }
  return csr;
}

void row(std::string_view name, std::int64_t bytes, std::int64_t blocks, std::ptrdiff_t n) {
  std::cout << std::format("{:<26}{:>12}{:>10}{:>12.1f}\n", name, bytes, blocks,
                           static_cast<double>(bytes) / static_cast<double>(n));
}

int main() {
  constexpr std::ptrdiff_t n = 1000;
  constexpr std::ptrdiff_t m = 3000;
  std::mt19937 gen{7};
  std::vector<Edge> edges;
  edges.reserve(static_cast<std::size_t>(m));
  for (std::ptrdiff_t i = 0; i < m; ++i)
    edges.push_back({.from = static_cast<std::ptrdiff_t>(gen() % static_cast<unsigned>(n)),
                     .to = static_cast<std::ptrdiff_t>(gen() % static_cast<unsigned>(n))});

  const std::vector<std::vector<std::ptrdiff_t>> lists = as_lists(n, edges);
  const Csr csr = as_csr(n, edges);
  const std::vector<char> matrix(static_cast<std::size_t>(n * n), 0);

  std::cout << std::format("1000 vertices, 3000 edges{:>15}{:>10}{:>12}\n", "bytes", "blocks", "per vertex");
  row("vector of vectors", bytes_of(lists), 1 + n, n);
  row("one flat pair (CSR)",
      static_cast<std::int64_t>((csr.offsets.capacity() + csr.targets.capacity()) * sizeof(std::ptrdiff_t)), 2, n);
  row("dense matrix of char", static_cast<std::int64_t>(matrix.capacity()), 1, n);

  std::int64_t degree_sum = 0;
  for (const std::vector<std::ptrdiff_t>& neighbours : lists) degree_sum += std::ssize(neighbours);
  std::cout << std::format("degrees add up to {} = 2m, and the CSR holds {} targets\n", degree_sum,
                           csr.targets.size());
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <queue>
#include <span>
#include <string>
#include <utility>
#include <vector>

using Graph = std::vector<std::vector<std::ptrdiff_t>>;

[[nodiscard]] Graph undirected(std::ptrdiff_t n, std::span<const std::pair<std::ptrdiff_t, std::ptrdiff_t>> edges) {
  Graph g(static_cast<std::size_t>(n));
  for (const auto& [a, b] : edges) {
    g[static_cast<std::size_t>(a)].push_back(b);
    g[static_cast<std::size_t>(b)].push_back(a);
  }
  for (std::vector<std::ptrdiff_t>& row : g) std::ranges::sort(row);  // a fixed neighbour order
  return g;
}

struct Search {
  std::vector<std::ptrdiff_t> order;                  // vertices in the order they were visited
  std::vector<std::optional<std::ptrdiff_t>> parent;  // who reached each vertex
  std::vector<std::optional<std::ptrdiff_t>> hops;    // edges from the start
};

[[nodiscard]] Search breadth_first(const Graph& g, std::ptrdiff_t start) {
  Search s;
  s.parent.assign(g.size(), std::nullopt);
  s.hops.assign(g.size(), std::nullopt);
  std::vector<char> seen(g.size(), 0);
  std::queue<std::ptrdiff_t> waiting;
  seen[static_cast<std::size_t>(start)] = 1;  // marked when it is queued
  s.hops[static_cast<std::size_t>(start)] = 0;
  waiting.push(start);
  while (!waiting.empty()) {
    const std::ptrdiff_t here = waiting.front();
    waiting.pop();
    s.order.push_back(here);
    for (const std::ptrdiff_t next : g[static_cast<std::size_t>(here)]) {
      if (seen[static_cast<std::size_t>(next)] != 0) continue;
      seen[static_cast<std::size_t>(next)] = 1;
      s.parent[static_cast<std::size_t>(next)] = here;
      s.hops[static_cast<std::size_t>(next)] = *s.hops[static_cast<std::size_t>(here)] + 1;
      waiting.push(next);
    }
  }
  return s;
}

[[nodiscard]] std::vector<std::ptrdiff_t> depth_first(const Graph& g, std::ptrdiff_t start) {
  std::vector<std::ptrdiff_t> order;
  std::vector<char> seen(g.size(), 0);
  std::vector<std::ptrdiff_t> pending{start};
  while (!pending.empty()) {
    const std::ptrdiff_t here = pending.back();
    pending.pop_back();
    if (seen[static_cast<std::size_t>(here)] != 0) continue;  // marked when it is taken
    seen[static_cast<std::size_t>(here)] = 1;
    order.push_back(here);
    const std::vector<std::ptrdiff_t>& neighbours = g[static_cast<std::size_t>(here)];
    for (auto it = neighbours.rbegin(); it != neighbours.rend(); ++it)
      if (seen[static_cast<std::size_t>(*it)] == 0) pending.push_back(*it);
  }
  return order;
}

[[nodiscard]] std::string show(std::span<const std::ptrdiff_t> v) {
  std::string out;
  for (const std::ptrdiff_t x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out.empty() ? "(none)" : out;
}

[[nodiscard]] std::string path_to(const Search& s, std::ptrdiff_t target) {
  if (!s.hops[static_cast<std::size_t>(target)]) return "unreachable";
  std::vector<std::ptrdiff_t> back;
  for (std::optional<std::ptrdiff_t> at = target; at; at = s.parent[static_cast<std::size_t>(*at)])
    back.push_back(*at);
  std::ranges::reverse(back);
  return show(back);
}

int main() {
  const std::vector<std::pair<std::ptrdiff_t, std::ptrdiff_t>> edges{{0, 1}, {0, 2}, {1, 3}, {1, 4}, {2, 4}, {3, 5}};
  const Graph g = undirected(7, edges);
  for (std::ptrdiff_t v = 0; v < std::ssize(g); ++v)
    std::cout << std::format("{} -> {}\n", v, show(g[static_cast<std::size_t>(v)]));

  const Search bfs = breadth_first(g, 0);
  std::cout << std::format("BFS order    {}\n", show(bfs.order));
  std::string hops;
  for (std::ptrdiff_t v = 0; v < std::ssize(g); ++v)
    hops += std::format("{}{}:{}", hops.empty() ? "" : " ", v,
                        bfs.hops[static_cast<std::size_t>(v)]
                            ? std::format("{}", *bfs.hops[static_cast<std::size_t>(v)])
                            : "-");
  std::cout << std::format("hops from 0  {}\n", hops);
  std::cout << std::format("path to 5    {}\n", path_to(bfs, 5));
  std::cout << std::format("path to 6    {}\n", path_to(bfs, 6));
  std::cout << std::format("DFS order    {}\n", show(depth_first(g, 0)));
}

#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <queue>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

using Graph = std::vector<std::vector<std::ptrdiff_t>>;

// Kahn's algorithm: repeatedly take a step whose prerequisites are all done.
// Returns the order, or no value when some steps can never start, which means a cycle.
[[nodiscard]] std::optional<std::vector<std::ptrdiff_t>> bring_up_order(const Graph& after) {
  std::vector<std::ptrdiff_t> waiting_on(after.size(), 0);
  for (const std::vector<std::ptrdiff_t>& nexts : after)
    for (const std::ptrdiff_t next : nexts) ++waiting_on[static_cast<std::size_t>(next)];
  std::queue<std::ptrdiff_t> ready;
  for (std::ptrdiff_t v = 0; v < std::ssize(after); ++v)
    if (waiting_on[static_cast<std::size_t>(v)] == 0) ready.push(v);
  std::vector<std::ptrdiff_t> order;
  while (!ready.empty()) {
    const std::ptrdiff_t here = ready.front();
    ready.pop();
    order.push_back(here);
    for (const std::ptrdiff_t next : after[static_cast<std::size_t>(here)])
      if (--waiting_on[static_cast<std::size_t>(next)] == 0) ready.push(next);
  }
  if (std::ssize(order) != std::ssize(after)) return std::nullopt;  // something never became ready
  return order;
}

[[nodiscard]] std::vector<std::ptrdiff_t> still_blocked(const Graph& after,
                                                        std::span<const std::ptrdiff_t> ordered) {
  std::vector<char> done(after.size(), 0);
  for (const std::ptrdiff_t v : ordered) done[static_cast<std::size_t>(v)] = 1;
  std::vector<std::ptrdiff_t> left;
  for (std::ptrdiff_t v = 0; v < std::ssize(after); ++v)
    if (done[static_cast<std::size_t>(v)] == 0) left.push_back(v);
  return left;
}

int main() {
  const std::vector<std::string> step{"udev-rules", "can-bus", "driver",    "odometry",
                                      "lidar",      "slam",    "navigation"};
  const std::vector<std::pair<std::ptrdiff_t, std::ptrdiff_t>> before{{0, 1}, {1, 2}, {2, 3}, {0, 4},
                                                                      {3, 5}, {4, 5}, {5, 6}};
  Graph after(step.size());
  for (const auto& [a, b] : before) after[static_cast<std::size_t>(a)].push_back(b);

  const std::optional<std::vector<std::ptrdiff_t>> order = bring_up_order(after);
  std::string line;
  for (const std::ptrdiff_t v : order.value())
    line += std::format("{}{}", line.empty() ? "" : " -> ", step[static_cast<std::size_t>(v)]);
  std::cout << std::format("bring-up order: {}\n", line);

  Graph broken = after;
  broken[6].push_back(1);  // navigation before can-bus: nonsense, and a cycle
  const std::optional<std::vector<std::ptrdiff_t>> none = bring_up_order(broken);
  std::cout << std::format("with navigation -> can-bus: order found: {}\n", none.has_value());

  // Kahn's partial result names the steps caught in the cycle.
  std::vector<std::ptrdiff_t> waiting_on(broken.size(), 0);
  for (const std::vector<std::ptrdiff_t>& nexts : broken)
    for (const std::ptrdiff_t next : nexts) ++waiting_on[static_cast<std::size_t>(next)];
  std::queue<std::ptrdiff_t> ready;
  for (std::ptrdiff_t v = 0; v < std::ssize(broken); ++v)
    if (waiting_on[static_cast<std::size_t>(v)] == 0) ready.push(v);
  std::vector<std::ptrdiff_t> placed;
  while (!ready.empty()) {
    const std::ptrdiff_t here = ready.front();
    ready.pop();
    placed.push_back(here);
    for (const std::ptrdiff_t next : broken[static_cast<std::size_t>(here)])
      if (--waiting_on[static_cast<std::size_t>(next)] == 0) ready.push(next);
  }
  std::string stuck;
  for (const std::ptrdiff_t v : still_blocked(broken, placed))
    stuck += std::format("{}{}", stuck.empty() ? "" : " ", step[static_cast<std::size_t>(v)]);
  std::cout << std::format("{} of {} steps placed, still blocked: {}\n", placed.size(), step.size(), stuck);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

using Edge = std::pair<std::ptrdiff_t, std::ptrdiff_t>;

struct Components {
  std::vector<std::ptrdiff_t> label;  // which component each vertex belongs to
  std::ptrdiff_t count = 0;
  std::ptrdiff_t largest = 0;
};

[[nodiscard]] Components components(std::ptrdiff_t n, std::span<const Edge> edges) {
  std::vector<std::vector<std::ptrdiff_t>> neighbours(static_cast<std::size_t>(n));
  for (const auto& [a, b] : edges) {
    neighbours[static_cast<std::size_t>(a)].push_back(b);
    neighbours[static_cast<std::size_t>(b)].push_back(a);
  }
  Components out;
  out.label.assign(static_cast<std::size_t>(n), -1);
  std::vector<std::ptrdiff_t> pending;
  for (std::ptrdiff_t start = 0; start < n; ++start) {
    if (out.label[static_cast<std::size_t>(start)] != -1) continue;
    const std::ptrdiff_t id = out.count++;
    std::ptrdiff_t size = 0;
    out.label[static_cast<std::size_t>(start)] = id;  // labelled when it is queued
    pending.push_back(start);
    while (!pending.empty()) {
      const std::ptrdiff_t here = pending.back();
      pending.pop_back();
      ++size;
      for (const std::ptrdiff_t next : neighbours[static_cast<std::size_t>(here)]) {
        if (out.label[static_cast<std::size_t>(next)] != -1) continue;
        out.label[static_cast<std::size_t>(next)] = id;
        pending.push_back(next);
      }
    }
    out.largest = std::max(out.largest, size);
  }
  return out;
}

[[nodiscard]] std::string show(std::span<const std::ptrdiff_t> v) {
  std::string out;
  for (const std::ptrdiff_t x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out.empty() ? "(none)" : out;
}

void report(std::string_view name, std::ptrdiff_t n, std::span<const Edge> edges) {
  const Components c = components(n, edges);
  std::cout << std::format("{:<24}{} components, largest {}, labels {}\n", name, c.count, c.largest,
                           show(c.label));
}

int main() {
  const std::vector<Edge> waypoints{{0, 1}, {0, 2}, {1, 3}, {1, 4}, {2, 4}, {3, 5}};
  report("7 vertices, 6 edges", 7, waypoints);
  report("5 vertices, no edges", 5, {});
  report("no vertices", 0, {});
  report("one vertex", 1, {});
  const std::vector<Edge> two{{0, 1}, {2, 3}};
  report("two pairs", 4, two);
  const std::vector<Edge> loop{{0, 1}, {1, 2}, {2, 0}};
  report("a triangle plus a spare", 4, loop);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <queue>
#include <span>
#include <string>
#include <string_view>
#include <vector>

struct Cell {
  std::ptrdiff_t row = 0;
  std::ptrdiff_t col = 0;
};

[[nodiscard]] bool operator==(const Cell& a, const Cell& b) { return a.row == b.row && a.col == b.col; }

struct Route {
  std::vector<Cell> cells;  // start first, goal last
  std::int64_t steps = 0;   // moves, which is one fewer than the cells
};

// The fewest moves from start to goal through '.' cells, or no value when there is no way through.
[[nodiscard]] std::optional<Route> shortest_route(std::span<const std::string> grid, Cell start, Cell goal) {
  const std::ptrdiff_t rows = std::ssize(grid);
  const std::ptrdiff_t cols = rows == 0 ? 0 : std::ssize(grid.front());
  const auto open = [&](Cell c) {
    return c.row >= 0 && c.row < rows && c.col >= 0 && c.col < cols &&
           grid[static_cast<std::size_t>(c.row)][static_cast<std::size_t>(c.col)] == '.';
  };
  if (!open(start) || !open(goal)) return std::nullopt;
  const auto id = [cols](Cell c) { return static_cast<std::size_t>(c.row * cols + c.col); };
  std::vector<std::optional<Cell>> came_from(static_cast<std::size_t>(rows * cols), std::nullopt);
  std::vector<char> seen(static_cast<std::size_t>(rows * cols), 0);
  std::queue<Cell> waiting;
  seen[id(start)] = 1;  // marked when it is queued
  waiting.push(start);
  while (!waiting.empty()) {
    const Cell here = waiting.front();
    waiting.pop();
    if (here == goal) {
      Route route;
      for (std::optional<Cell> at = here; at; at = came_from[id(*at)]) route.cells.push_back(*at);
      std::ranges::reverse(route.cells);
      route.steps = std::ssize(route.cells) - 1;
      return route;
    }
    const std::vector<Cell> around{
        {here.row - 1, here.col}, {here.row + 1, here.col}, {here.row, here.col - 1}, {here.row, here.col + 1}};
    for (const Cell& next : around) {
      if (!open(next) || seen[id(next)] != 0) continue;
      seen[id(next)] = 1;
      came_from[id(next)] = here;
      waiting.push(next);
    }
  }
  return std::nullopt;
}

void report(std::string_view name, std::span<const std::string> grid, Cell start, Cell goal) {
  const std::optional<Route> route = shortest_route(grid, start, goal);
  if (!route) {
    std::cout << std::format("{:<26}no way through\n", name);
    return;
  }
  std::string path;
  for (const Cell& c : route->cells) path += std::format("{}({},{})", path.empty() ? "" : " ", c.row, c.col);
  std::cout << std::format("{:<26}{} steps: {}\n", name, route->steps, path);
}

int main() {
  const std::vector<std::string> room{".....", ".###.", ".#...", ".#.#.", "...#."};
  for (const std::string& line : room) std::cout << line << '\n';
  report("(0,0) to (4,4)", room, {0, 0}, {4, 4});
  report("(0,0) to (0,0)", room, {0, 0}, {0, 0});
  report("(0,0) to (2,2)", room, {0, 0}, {2, 2});
  report("(0,0) to (1,1), a wall", room, {0, 0}, {1, 1});
  const std::vector<std::string> split{"..#..", "..#..", "..#.."};
  report("across a full wall", split, {0, 0}, {0, 4});
}

#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <queue>
#include <string_view>
#include <vector>

using Graph = std::vector<std::vector<std::ptrdiff_t>>;

struct Cost {
  std::int64_t pushes = 0;
  std::ptrdiff_t widest = 0;
  std::int64_t hops_to_last = 0;
};

// Correct: a vertex is marked the moment it is put in the queue.
[[nodiscard]] Cost mark_on_push(const Graph& g) {
  Cost cost;
  std::vector<char> seen(g.size(), 0);
  std::vector<std::int64_t> hops(g.size(), 0);
  std::queue<std::ptrdiff_t> waiting;
  seen[0] = 1;
  waiting.push(0);
  ++cost.pushes;
  while (!waiting.empty()) {
    cost.widest = std::max(cost.widest, std::ssize(waiting));
    const std::ptrdiff_t here = waiting.front();
    waiting.pop();
    for (const std::ptrdiff_t next : g[static_cast<std::size_t>(here)]) {
      if (seen[static_cast<std::size_t>(next)] != 0) continue;
      seen[static_cast<std::size_t>(next)] = 1;
      hops[static_cast<std::size_t>(next)] = hops[static_cast<std::size_t>(here)] + 1;
      waiting.push(next);
      ++cost.pushes;
    }
  }
  cost.hops_to_last = hops.back();
  return cost;
}

// The bug: a vertex is marked only when it comes out, so it is queued once per neighbour that
// reached it first. The answers still come out right, which is why nobody notices.
[[nodiscard]] Cost mark_on_pop(const Graph& g) {
  Cost cost;
  std::vector<char> seen(g.size(), 0);
  std::vector<std::int64_t> hops(g.size(), 0);
  std::queue<std::ptrdiff_t> waiting;
  waiting.push(0);
  ++cost.pushes;
  while (!waiting.empty()) {
    cost.widest = std::max(cost.widest, std::ssize(waiting));
    const std::ptrdiff_t here = waiting.front();
    waiting.pop();
    if (seen[static_cast<std::size_t>(here)] != 0) continue;
    seen[static_cast<std::size_t>(here)] = 1;
    for (const std::ptrdiff_t next : g[static_cast<std::size_t>(here)]) {
      if (seen[static_cast<std::size_t>(next)] != 0) continue;
      hops[static_cast<std::size_t>(next)] = hops[static_cast<std::size_t>(here)] + 1;
      waiting.push(next);
      ++cost.pushes;
    }
  }
  cost.hops_to_last = hops.back();
  return cost;
}

void row(std::string_view shape, const Graph& g) {
  const Cost good = mark_on_push(g);
  const Cost bad = mark_on_pop(g);
  std::cout << std::format("{:<20}{:>9}{:>9}{:>9}{:>9}{:>8}{:>6}\n", shape, good.pushes, bad.pushes, good.widest,
                           bad.widest, good.hops_to_last, bad.hops_to_last);
}

[[nodiscard]] Graph complete(std::ptrdiff_t n) {
  Graph g(static_cast<std::size_t>(n));
  for (std::ptrdiff_t a = 0; a < n; ++a)
    for (std::ptrdiff_t b = 0; b < n; ++b)
      if (a != b) g[static_cast<std::size_t>(a)].push_back(b);
  return g;
}

[[nodiscard]] Graph grid(std::ptrdiff_t side) {
  Graph g(static_cast<std::size_t>(side * side));
  const auto id = [side](std::ptrdiff_t r, std::ptrdiff_t c) { return r * side + c; };
  for (std::ptrdiff_t r = 0; r < side; ++r)
    for (std::ptrdiff_t c = 0; c < side; ++c) {
      if (r + 1 < side) {
        g[static_cast<std::size_t>(id(r, c))].push_back(id(r + 1, c));
        g[static_cast<std::size_t>(id(r + 1, c))].push_back(id(r, c));
      }
      if (c + 1 < side) {
        g[static_cast<std::size_t>(id(r, c))].push_back(id(r, c + 1));
        g[static_cast<std::size_t>(id(r, c + 1))].push_back(id(r, c));
      }
    }
  return g;
}

int main() {
  std::cout << std::format("{:<20}{:>9}{:>9}{:>9}{:>9}{:>8}{:>6}\n", "graph", "pushes", "late", "widest", "late",
                           "hops", "late");
  row("200 all joined", complete(200));
  row("100 by 100 grid", grid(100));
}

#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

using Graph = std::vector<std::vector<std::ptrdiff_t>>;

// A corridor: every cell joined to the next one, the shape a wall-following map produces.
[[nodiscard]] Graph corridor(std::ptrdiff_t n) {
  Graph g(static_cast<std::size_t>(n));
  for (std::ptrdiff_t v = 0; v + 1 < n; ++v) {
    g[static_cast<std::size_t>(v)].push_back(v + 1);
    g[static_cast<std::size_t>(v + 1)].push_back(v);
  }
  return g;
}

std::int64_t visit(const Graph& g, std::ptrdiff_t here, std::vector<char>& seen) {
  seen[static_cast<std::size_t>(here)] = 1;
  std::int64_t reached = 1;
  for (const std::ptrdiff_t next : g[static_cast<std::size_t>(here)])
    if (seen[static_cast<std::size_t>(next)] == 0) reached += visit(g, next, seen);
  return reached;
}

int main() {
  const Graph g = corridor(1'000'000);
  std::vector<char> seen(g.size(), 0);
  std::cout << std::format("reached {} cells\n", visit(g, 0, seen));
}
